import * as T from './vendor/three.module.js';
export function decorateMorningHome(group){
 const wood=new T.MeshStandardMaterial({color:0x6f5542,roughness:.7}),cloth=new T.MeshStandardMaterial({color:0xe1dfd3,roughness:1}),blue=new T.MeshStandardMaterial({color:0x627f89,roughness:1});
 const box=(p,w,h,d,mat,x,y,z)=>{const m=new T.Mesh(new T.BoxGeometry(w,h,d),mat);m.position.set(x,y,z);p.add(m);return m;};
 const bed=new T.Group();bed.name='Bed with pillows and draped duvet';bed.position.set(-5,0,4.5);group.add(bed);
 box(bed,2.5,.23,3.8,wood,0,.48,0);for(const x of [-1.05,1.05])for(const z of [-1.6,1.6])box(bed,.12,.37,.12,wood,x,.18,z);box(bed,2.5,1.1,.13,wood,0,.88,-1.86);
 const mattress=new T.Mesh(new T.SphereGeometry(1,32,18),cloth);mattress.scale.set(1.23,.22,1.9);mattress.position.y=.78;bed.add(mattress);
 for(const x of [-.55,.55]){const pillow=new T.Mesh(new T.SphereGeometry(1,24,16),cloth);pillow.name='Soft bed pillow';pillow.scale.set(.5,.12,.3);pillow.position.set(x,1.02,-1.55);pillow.rotation.y=x*.12;bed.add(pillow);}
 const duvetGeo=new T.PlaneGeometry(2.75,2.85,32,30),a=duvetGeo.attributes.position;for(let i=0;i<a.count;i++){const x=a.getX(i),z=a.getY(i),edge=Math.max(0,Math.abs(x)-1.05);a.setXYZ(i,x,.99-edge*1.25+Math.sin(x*12+z*2)*.025+Math.cos(z*9)*.014,z+.42);}duvetGeo.computeVertexNormals();const duvet=new T.Mesh(duvetGeo,blue);duvet.material.side=T.DoubleSide;duvet.name='Draped fabric duvet';bed.add(duvet);
 const bag=new T.Group();bag.name='Wearable work backpack';bag.position.set(4,1.13,1);group.add(bag);const bagMat=new T.MeshStandardMaterial({color:0x3d5962,roughness:.9});const body=new T.Mesh(new T.SphereGeometry(1,20,16),bagMat);body.scale.set(.24,.3,.13);bag.add(body);box(bag,.32,.19,.08,bagMat,0,-.08,.12);box(bag,.29,.014,.02,wood,0,.015,.17);for(const x of [-.14,.14]){const strap=new T.Mesh(new T.TorusGeometry(.12,.018,6,20),bagMat);strap.scale.set(.6,1.3,1);strap.position.set(x,0,-.12);bag.add(strap);}const handle=new T.Mesh(new T.TorusGeometry(.07,.014,6,20),bagMat);handle.position.y=.29;bag.add(handle);
 const tv=new T.Group();tv.name='Morning news television';tv.position.set(-5,1.65,-6.9);group.add(tv);const black=new T.MeshStandardMaterial({color:0x172329,roughness:.3});box(tv,2.6,1.55,.1,black,0,0,0);box(tv,.1,.35,.1,black,0,-.9,0);box(tv,1,.06,.45,black,0,-1.08,0);
 const canvas=document.createElement('canvas');canvas.width=768;canvas.height=432;const ctx=canvas.getContext('2d'),texture=new T.CanvasTexture(canvas);texture.colorSpace=T.SRGBColorSpace;const screen=new T.Mesh(new T.PlaneGeometry(2.47,1.39),new T.MeshBasicMaterial({map:texture}));screen.position.z=.06;tv.add(screen);let tick=-1;
 function update(t){const frame=Math.floor(t*8);if(frame===tick)return;tick=frame;ctx.fillStyle='#183d59';ctx.fillRect(0,0,768,432);ctx.fillStyle='#306080';for(let i=0;i<7;i++)ctx.fillRect(i*115,80+(i%3)*17,75,220);ctx.fillStyle='#d2a389';ctx.beginPath();ctx.ellipse(384,158,51,66,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#25363e';ctx.fillRect(322,224,124,120);ctx.fillStyle='#45362f';ctx.fillRect(341,95,86,22);ctx.fillStyle='#583e36';ctx.fillRect(372,188,24,frame%3?5:10);ctx.fillStyle='#829ba8';ctx.fillRect(220,301,330,45);ctx.fillStyle='#b02932';ctx.fillRect(0,344,768,88);ctx.fillStyle='#fff';ctx.direction='rtl';ctx.textAlign='right';ctx.font='bold 36px Arial';ctx.fillText('חדשות הבוקר',735,52);ctx.font='24px Arial';ctx.fillText('פריצת דרך בחקר קורי המשי באחוזת המחקר',735,384);ctx.font='18px Arial';ctx.fillText('שידור בדיוני מתוך עולם המשחק',735,419);texture.needsUpdate=true;}
 update(0);return{bed,bag,tv,update};
}
